import { spawnSync } from "node:child_process";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  buildCatalogFrameworkDefaultsV1,
  serializeCatalogDefaultV1,
} from "../dist/production/catalog-defaults-v1.js";

function committedBytes(root, path) {
  const result = spawnSync("git", ["show", `HEAD:${path}`], {
    cwd: root,
    encoding: "buffer",
    windowsHide: true,
    maxBuffer: 32 * 1024 * 1024,
  });
  if (result.status !== 0) throw new Error(`catalog-defaults: cannot read HEAD:${path}`);
  return result.stdout;
}

/** Compare generated bytes with the exact HEAD blobs, including after a build rewrites defaults. */
export function checkCommittedCatalogDefaults(root, readCommitted = committedBytes) {
  const generated = buildCatalogFrameworkDefaultsV1(root);
  const paths = Object.keys(generated).sort();
  if (paths.length !== 8) throw new Error(`catalog-defaults: expected 8 generated defaults, got ${paths.length}`);
  for (const path of paths) {
    const bytes = Buffer.from(serializeCatalogDefaultV1(generated[path]));
    const committed = readCommitted(root, path);
    if (!Buffer.isBuffer(committed) || !committed.equals(bytes)) {
      throw new Error(`catalog-defaults: ${path} is stale in HEAD`);
    }
  }
  return paths;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const root = resolve(process.argv[2] ?? resolve(import.meta.dirname, ".."));
    const paths = checkCommittedCatalogDefaults(root);
    console.log(`Checked ${paths.length} generated defaults against HEAD bytes`);
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}
